// Attack defines model for Attack.
type Attack struct {
	Attacker *AttackPlayer `json:"attacker"`

	// Chain Important! Starting January 1st, 2027, the value '0' will be replaced with 'null'.
	Chain    *int32       `json:"chain"`
	Code     AttackCode   `json:"code"`
	Defender AttackPlayer `json:"defender"`

	// Ended Attack end timestamp.
	Ended               int32                          `json:"ended"`
	FinishingHitEffects []AttackingFinishingHitEffects `json:"finishing_hit_effects"`
	Id                  AttackId                       `json:"id"`

	// IsInterrupted This is an experimental flag which should help determine 'assist' attacks which have not contributed to the chain. For example, attacks such as where the opponent lost to someoene else before the attacker could finish the attack. This flag might not work entirely correctly, so use with caution.
	IsInterrupted  bool `json:"is_interrupted"`
	IsRaid         bool `json:"is_raid"`
	IsRankedWar    bool `json:"is_ranked_war"`
	IsStealthed    bool `json:"is_stealthed"`
	IsTerritoryWar bool `json:"is_territory_war"`
	Modifiers      struct {
		Chain       float32 `json:"chain"`
		FairFight   float32 `json:"fair_fight"`
		Group       float32 `json:"group"`
		Overseas    float32 `json:"overseas"`
		Retaliation float32 `json:"retaliation"`
		War         float32 `json:"war"`
		Warlord     float32 `json:"warlord"`
	} `json:"modifiers"`
	RespectGain float32             `json:"respect_gain"`
	RespectLoss float32             `json:"respect_loss"`
	Result      FactionAttackResult `json:"result"`

	// Started Attack start timestamp.
	Started        int32           `json:"started"`
	TerritoryWarId *TerritoryWarId `json:"territory_war_id"`
}

